STYLE='\n#nativeAttemptIncrement16{margin-top:3rem;border-top:3px solid #27798b;padding-top:1.3rem;overflow-wrap:anywhere}\n#nativeAttemptIncrement16 .r16-en{display:none}\n#nativeAttemptIncrement16 .r16-title-en{display:none}\n#nativeAttemptIncrement16:has(#r16LanguageEN:checked) .r16-title-zh{display:none}\n#nativeAttemptIncrement16:has(#r16LanguageEN:checked) .r16-title-en{display:block}\n#nativeAttemptIncrement16>input[type=radio]{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);clip-path:inset(50%);white-space:nowrap;border:0}\n#nativeAttemptIncrement16 .r16-controls label{padding:.35rem .5rem;cursor:pointer;border:1px solid transparent;border-radius:.2rem}\n#r16LanguageZH:checked~.r16-controls label[for=r16LanguageZH],#r16LanguageEN:checked~.r16-controls label[for=r16LanguageEN],#r16Detailed:checked~.r16-controls label[for=r16Detailed],#r16Summary:checked~.r16-controls label[for=r16Summary]{background:#e5eef1;border-color:#27798b;font-weight:600}\n#r16LanguageZH:focus-visible~.r16-controls label[for=r16LanguageZH],#r16LanguageEN:focus-visible~.r16-controls label[for=r16LanguageEN],#r16Detailed:focus-visible~.r16-controls label[for=r16Detailed],#r16Summary:focus-visible~.r16-controls label[for=r16Summary]{outline:3px solid #164c70;outline-offset:3px}\n\n#r16LanguageEN:checked~.r16-content .r16-zh{display:none}#r16LanguageEN:checked~.r16-content .r16-en{display:block}\n#r16Summary:checked~.r16-content .r16-detail{display:none}\n.r16-controls{border:1px solid #ccd6da;padding:1rem;margin:1rem 0}.r16-controls label{display:inline-block;margin-right:1rem}\n.r16-cards{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:.7rem;margin:1.2rem 0}\n.r16-cards>div{padding:1rem;background:#f1f5f6;border:1px solid #cbd7db}.r16-cards strong{display:block;font-size:1.1rem;margin-top:.35rem}\n.r16-table-wrap{max-width:100%;overflow-x:auto}#r16StageTable{width:100%;min-width:740px;border-collapse:collapse}\n#r16StageTable th,#r16StageTable td{text-align:left;padding:.8rem;vertical-align:top;border-bottom:1px solid #d7e1e5}\n#r16EvidenceAppendix{margin:1.4rem 0;padding:1rem;background:#f6f8f9}#r16EvidenceAppendix code{overflow-wrap:anywhere;word-break:break-word}\n@media(max-width:640px){.r16-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.r16-cards>div:last-child{grid-column:1/-1}}\n'
